-- ============================================================================
-- EduFlow — 0002_seed.sql
-- Seed determinístico a partir de src/data/mockData.ts e src/lib/servicos.ts.
-- UUIDs fixos para entidades estáveis (idempotente). Aulas geradas via
-- md5(...)::uuid relativo à semana atual (semana anterior = realizada/presente;
-- semana atual = agendada) — análogo fixo de generateAulas() (que é aleatório).
-- ============================================================================

-- ── centro ──────────────────────────────────────────────────────────────────

-- ── disciplinas ─────────────────────────────────────────────────────────────

-- ── users (6 mock + 5 explicadores adicionais; u3 = e1 João Ferreira) ───────

-- ── professor_perfis (e1 via u3; e2..e6 via e-users) ────────────────────────

-- ── disponibilidades ────────────────────────────────────────────────────────

-- ── professor_disciplinas ───────────────────────────────────────────────────

-- ── salas ───────────────────────────────────────────────────────────────────

-- ── servicos + tiers ────────────────────────────────────────────────────────


-- ── alunos ──────────────────────────────────────────────────────────────────
-- explicador_user_id: e1→u3(a0..03), e2→e0..02, e3→e0..03, e4→e0..04, e5→e0..05
-- encarregado_user_id: a1→u4, a2→u5, a3→u6, restantes NULL

-- ── alunos_disciplinas ──────────────────────────────────────────────────────

-- ── aulas (semana anterior = realizada/presente; semana atual = agendada) ───
-- 15 slots × 2 semanas + 2 sobrepostas. id = md5('aula-'||wk||'-'||idx)::uuid
with wk(n, monday, estado) as (
  values
    (0, (date_trunc('week', current_date)::date - 7), 'realizada'),
    (1, (date_trunc('week', current_date)::date),     'agendada')
),
slot(idx, exp_uuid, sala_uuid, disc_uuid, tipo, day_off, hi, hf) as (
  values
    (0 ,'a0000000-0000-0000-0000-000000000003','50000000-0000-0000-0000-000000000001','d0000000-0000-0000-0000-000000000001','individual',0,time '09:00',time '10:00'),
    (1 ,'a0000000-0000-0000-0000-000000000003','50000000-0000-0000-0000-000000000001','d0000000-0000-0000-0000-000000000004','individual',0,time '10:00',time '11:00'),
    (2 ,'e0000000-0000-0000-0000-000000000002','50000000-0000-0000-0000-000000000004','d0000000-0000-0000-0000-000000000002','individual',0,time '11:00',time '12:00'),
    (3 ,'e0000000-0000-0000-0000-000000000002','50000000-0000-0000-0000-000000000002','d0000000-0000-0000-0000-000000000002','grupo'     ,1,time '09:00',time '10:00'),
    (4 ,'e0000000-0000-0000-0000-000000000003','50000000-0000-0000-0000-000000000001','d0000000-0000-0000-0000-000000000003','individual',1,time '10:00',time '11:00'),
    (5 ,'e0000000-0000-0000-0000-000000000003','50000000-0000-0000-0000-000000000004','d0000000-0000-0000-0000-000000000003','individual',1,time '11:00',time '12:00'),
    (6 ,'e0000000-0000-0000-0000-000000000004','50000000-0000-0000-0000-000000000001','d0000000-0000-0000-0000-000000000005','individual',2,time '09:00',time '10:00'),
    (7 ,'e0000000-0000-0000-0000-000000000004','50000000-0000-0000-0000-000000000002','d0000000-0000-0000-0000-000000000005','grupo'     ,2,time '10:00',time '11:00'),
    (8 ,'e0000000-0000-0000-0000-000000000005','50000000-0000-0000-0000-000000000001','d0000000-0000-0000-0000-000000000006','individual',2,time '11:00',time '12:00'),
    (9 ,'e0000000-0000-0000-0000-000000000005','50000000-0000-0000-0000-000000000003','d0000000-0000-0000-0000-000000000001','grupo'     ,3,time '09:00',time '10:00'),
    (10,'a0000000-0000-0000-0000-000000000003','50000000-0000-0000-0000-000000000004','d0000000-0000-0000-0000-000000000001','individual',3,time '10:00',time '11:00'),
    (11,'e0000000-0000-0000-0000-000000000002','50000000-0000-0000-0000-000000000001','d0000000-0000-0000-0000-000000000008','individual',3,time '11:00',time '12:00'),
    (12,'a0000000-0000-0000-0000-000000000003','50000000-0000-0000-0000-000000000001','d0000000-0000-0000-0000-000000000001','individual',4,time '09:00',time '10:00'),
    (13,'e0000000-0000-0000-0000-000000000004','50000000-0000-0000-0000-000000000004','d0000000-0000-0000-0000-000000000004','individual',4,time '10:00',time '11:00'),
    (14,'e0000000-0000-0000-0000-000000000003','50000000-0000-0000-0000-000000000001','d0000000-0000-0000-0000-000000000003','individual',4,time '11:00',time '12:00')
)
select md5('aula-'||wk.n||'-'||slot.idx)::uuid,
       'c0000000-0000-0000-0000-000000000001',
       slot.sala_uuid::uuid, slot.disc_uuid::uuid,
       wk.monday + slot.day_off, slot.hi, slot.hf,
       slot.tipo, wk.estado, 'semanal'
from wk cross join slot;

