with wk(n) as (values (0),(1)),
slot(idx, exp_uuid) as (
  values
    (0,'a0000000-0000-0000-0000-000000000003'),(1,'a0000000-0000-0000-0000-000000000003'),
    (2,'e0000000-0000-0000-0000-000000000002'),(3,'e0000000-0000-0000-0000-000000000002'),
    (4,'e0000000-0000-0000-0000-000000000003'),(5,'e0000000-0000-0000-0000-000000000003'),
    (6,'e0000000-0000-0000-0000-000000000004'),(7,'e0000000-0000-0000-0000-000000000004'),
    (8,'e0000000-0000-0000-0000-000000000005'),(9,'e0000000-0000-0000-0000-000000000005'),
    (10,'a0000000-0000-0000-0000-000000000003'),(11,'e0000000-0000-0000-0000-000000000002'),
    (12,'a0000000-0000-0000-0000-000000000003'),(13,'e0000000-0000-0000-0000-000000000004'),
