-- aula_alunos (+ presença: 'presente' na semana anterior, NULL na atual)
with wk(n, pres) as (values (0,'presente'::text), (1, NULL::text)),
slot_aluno(idx, aluno_uuid) as (
  values
    (0 ,'a1000000-0000-0000-0000-000000000001'),
    (1 ,'a1000000-0000-0000-0000-000000000002'),
    (2 ,'a1000000-0000-0000-0000-000000000003'),
    (3 ,'a1000000-0000-0000-0000-000000000004'),(3 ,'a1000000-0000-0000-0000-000000000009'),
    (4 ,'a1000000-0000-0000-0000-000000000004'),
    (5 ,'a1000000-0000-0000-0000-000000000007'),
    (6 ,'a1000000-0000-0000-0000-000000000008'),
    (7 ,'a1000000-0000-0000-0000-000000000002'),(7 ,'a1000000-0000-0000-0000-000000000008'),
    (8 ,'a1000000-0000-0000-0000-000000000005'),
    (9 ,'a1000000-0000-0000-0000-000000000001'),(9 ,'a1000000-0000-0000-0000-000000000005'),(9 ,'a1000000-0000-0000-0000-000000000006'),
    (10,'a1000000-0000-0000-0000-000000000006'),
    (11,'a1000000-0000-0000-0000-000000000003'),
    (12,'a1000000-0000-0000-0000-000000000009'),
    (13,'a1000000-0000-0000-0000-000000000001'),
    (14,'a1000000-0000-0000-0000-000000000010')
)
select md5('aula-'||wk.n||'-'||slot_aluno.idx)::uuid, slot_aluno.aluno_uuid::uuid, wk.pres
from wk cross join slot_aluno;

